export function formatCents(cents: number): string {
	const sign = cents < 0 ? '-' : '';
	const abs = Math.abs(cents);
	const dollars = Math.floor(abs / 100);
	const rest = String(abs % 100).padStart(2, '0');
	return sign + '$' + dollars + '.' + rest;
}

/** Renders a list of labeled cent amounts as a receipt with a total (see SPEC.md). */
export function formatReceipt(lines: Array<{ label: string; cents: number }>): string {
	const itemLines = lines.map(({ label, cents }) => `${label}: ${formatCents(cents)}`);
	const total = lines.reduce((sum, line) => sum + line.cents, 0);
	itemLines.push(`Total: ${formatCents(total)}`);
	return itemLines.join('\n');
}
```

